file.content:
  transition: background 0.2s, transform 0.2s;
}

#safecast-ai-toggle:hover {
  background: #388e3c;
  transform: scale(1.05);
}

#safecast-ai-panel {
  position: fixed;
  top: 10px;
  left: -470px;
  width: 450px;
  height: calc(100% - 20px);
  background: var(--modal-bg);
  color: var(--modal-text);
  box-shadow: 4px 0 20px rgba(0, 0, 0, 0.3);
  z-index: 2001;
  display: flex;
  flex-direction: column;
  border-radius: 12px;
  border: var(--modal-border);
  font-family: var(--font-family-base);
  margin-left: 10px;
}

#safecast-ai-panel.open {
  left: 10px;
}

#safecast-ai-panel.expanded {
  width: 700px;
  max-width: 90vw;
}

.ai-panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  border-bottom: 1px solid var(--modal-border);
}

.ai-panel-header-text h3 {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  color: var(--modal-text);
}

.ai-panel-header-text span {
  font-size: 11px;
  color: var(--modal-text); opacity: 0.7;
  display: block;
}

.ai-header-actions {
  display: flex;
  gap: 8px;
}

