.ai-panel-messages {
  flex: 1;
  overflow-y: auto;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  background: var(--modal-bg);
}

#ai-panel-input-container {
  padding: 20px;
  padding-top: 10px;
  background: transparent;
}

#ai-disclaimer {
  margin: 8px 0 0 0;
  font-size: 10px;
  line-height: 1.4;
  color: var(--modal-text); opacity: 0.7;
  text-align: center;
}

#ai-form {
  position: relative;
  background: var(--control-bg);
  border-radius: 24px;
  padding: 4px;
  display: flex;
  align-items: center;
  box-shadow: inset 0 1px 4px rgba(0, 0, 0, 0.1);
  border: 1px solid var(--modal-border);
  transition: all 0.2s;
}

#ai-form:focus-within {
  background: var(--modal-bg);
  box-shadow: 0 4px 20px rgba(76, 175, 80, 0.1), inset 0 1px 2px rgba(0, 0, 0, 0.02);
  border-color: rgba(76, 175, 80, 0.3);
}

#ai-msg {
  flex: 1;
  background: transparent;
  color: var(--modal-text);
  border: none;
  padding: 10px 48px 10px 16px;
  font-family: inherit;
  font-size: var(--font-size-base);
  resize: none;
  max-height: 150px;
  min-height: 24px;
  line-height: 22px;
  outline: none;
}

#ai-send {
  background: #4caf50;
  border: none;
  border-radius: 50%;
  width: 36px;
  height: 36px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: white;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: 0 4px 10px rgba(76, 175, 80, 0.3);
  margin-right: 2px;
}

#ai-send:hover:not(:disabled) {
  background: #388e3c;
  transform: scale(1.05);
  box-shadow: 0 6px 15px rgba(76, 175, 80, 0.4);
}

#ai-search-map {
  position: absolute;
  right: 48px;
  top: 50%;
  transform: translateY(-50%);
  background: transparent;
  border: none;
  color: var(--modal-text); opacity: 0.7;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  transition: all 0.2s;
}

